create table public.teams (id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users (id) on delete cascade, name text not null);
create table public.team_members (team_id uuid not null references public.teams (id) on delete cascade, user_id uuid not null references auth.users (id) on delete cascade, primary key (team_id, user_id));
create table public.team_documents (id uuid primary key default gen_random_uuid(), team_id uuid not null references public.teams (id) on delete cascade, title text not null, body text);
alter table public.teams enable row level security;
alter table public.team_members enable row level security;
alter table public.team_documents enable row level security;
create function public.is_team_member(tid uuid) returns boolean language sql security definer stable set search_path = public as $$ select exists (select 1 from public.team_members where team_id = tid and user_id = auth.uid()) $$;
create function public.is_team_owner(tid uuid) returns boolean language sql security definer stable set search_path = public as $$ select exists (select 1 from public.teams where id = tid and owner_id = auth.uid()) $$;
create policy "team members read documents" on public.team_documents for select using (public.is_team_member(team_id));
create policy "team owners add members" on public.team_members for insert with check (public.is_team_owner(team_id));
